import{_ as s,a as o,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 全册短语与句型 · 第1–23课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第二册：实践与进步 · 全册短语与句型 · 第1–23课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-2/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册短语与句型","link":"/life/english/new-concept/book-2/phrases"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-2/phrases-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册短语与句型","link":"/life/english/new-concept/book-2/phrases"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-2/phrases-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/phrases-part-01.md","filePath":"life/english/new-concept/book-2/phrases-part-01.md"}'),l={name:"life/english/new-concept/book-2/phrases-part-01.md"};function i(t,e,r,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第二册-实践与进步-·-全册短语与句型-·-第1–23课" tabindex="-1">第二册：实践与进步 · 全册短语与句型 · 第1–23课 <a class="header-anchor" href="#第二册-实践与进步-·-全册短语与句型-·-第1–23课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册短语与句型 · 第1–23课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="第二册-实践与进步-·-全册短语与句型" tabindex="-1">第二册：实践与进步 · 全册短语与句型 <a class="header-anchor" href="#第二册-实践与进步-·-全册短语与句型" aria-label="Permalink to &quot;第二册：实践与进步 · 全册短语与句型 {#第二册-实践与进步-·-全册短语与句型}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="lesson-1-·-一般过去时与事件顺序" tabindex="-1">Lesson 1 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-1-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 1 · 一般过去时与事件顺序 {#lesson-1-·-一般过去时与事件顺序}&quot;">​</a></h2><ul><li>lower your voice — 压低声音；voice 前用物主代词</li><li>pay attention to — 注意；to 后接名词或动名词</li></ul><p><strong>句型示范：</strong> Maya closed her book quietly after the discussion.</p><p>Maya 是主语，closed 是过去式谓语，her book 是宾语，quietly 是方式状语，after 短语标记时间。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-001">进入本课</a></p><h2 id="lesson-2-·-一般现在时与习惯" tabindex="-1">Lesson 2 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-2-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 2 · 一般现在时与习惯 {#lesson-2-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>get up — 起床，不等于醒来</li><li>on weekdays — 在工作日，复数表示通常的周一至周五</li></ul><p><strong>句型示范：</strong> Leo usually eats breakfast before seven.</p><p>Leo 是单数主语，eats 是习惯性动作，usually 位于实义动词前，before seven 给出时间边界。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-002">进入本课</a></p><h2 id="lesson-3-·-动词、宾语与补足语" tabindex="-1">Lesson 3 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-3-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 3 · 动词、宾语与补足语 {#lesson-3-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>send something to somebody — 把某物寄给某人</li><li>write down an address — 记下地址，代词可放在 write 与 down 之间</li></ul><p><strong>句型示范：</strong> Nina sent her uncle a postcard from the island.</p><p>Nina 是主语，sent 是 send 的过去式，her uncle 是间接宾语，a postcard 是直接宾语，from 短语说明寄出地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-003">进入本课</a></p><h2 id="lesson-4-·-现在完成时与过去时间" tabindex="-1">Lesson 4 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-4-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 4 · 现在完成时与过去时间 {#lesson-4-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>travel abroad — 到国外旅行，abroad 前不加 to</li><li>so far — 到目前为止，常与完成时相配</li></ul><p><strong>句型示范：</strong> Iris has visited three coastal towns this month.</p><p>has visited 表示本月到现在的经历；three coastal towns 是已完成的数量，this month 在此被理解为尚未结束的时间段。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-004">进入本课</a></p><h2 id="lesson-5-·-现在完成时与过去时间" tabindex="-1">Lesson 5 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-5-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 5 · 现在完成时与过去时间 {#lesson-5-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>keep in contact — 保持联系</li><li>send a signal — 发出信号，signal 是可数名词</li></ul><p><strong>句型示范：</strong> Our studio has received six messages today.</p><p>Our studio 是整体单数主语，所以用 has；six messages 表示累计结果，today 的时间范围延伸到现在。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-005">进入本课</a></p><h2 id="lesson-6-·-冠词与可数性" tabindex="-1">Lesson 6 · 冠词与可数性 <a class="header-anchor" href="#lesson-6-·-冠词与可数性" aria-label="Permalink to &quot;Lesson 6 · 冠词与可数性 {#lesson-6-·-冠词与可数性}&quot;">​</a></h2><ul><li>a slice of bread — 一片面包，用 slice 计数</li><li>in return for — 作为对……的回报，for 后接所交换的帮助或物品</li></ul><p><strong>句型示范：</strong> A neighbour brought me some bread after the storm.</p><p>A neighbour 首次引入人物；some bread 是不可数名词短语；brought 带 me 与 some bread 两个宾语。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-006">进入本课</a></p><h2 id="lesson-7-·-过去进行时与叙事背景" tabindex="-1">Lesson 7 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-7-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 7 · 过去进行时与叙事背景 {#lesson-7-·-过去进行时与叙事背景}&quot;">​</a></h2><ul><li>wait for — 等待某人或某物，不能漏 for</li><li>too late to do — 太迟而不能做某事</li></ul><p><strong>句型示范：</strong> The guards were checking the gate when the parcel arrived.</p><p>主句 were checking 是背景，when 从句 arrived 是介入事件；guards 是复数，所以不能用 was。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-007">进入本课</a></p><h2 id="lesson-8-·-比较级与比较范围" tabindex="-1">Lesson 8 · 比较级与比较范围 <a class="header-anchor" href="#lesson-8-·-比较级与比较范围" aria-label="Permalink to &quot;Lesson 8 · 比较级与比较范围 {#lesson-8-·-比较级与比较范围}&quot;">​</a></h2><ul><li>win a prize — 获奖，不能用 earn 表示所有比赛获奖情形</li><li>the best of the three — 三者中最好的，明确比较范围</li></ul><p><strong>句型示范：</strong> Lena&#39;s garden is smaller but neater than mine.</p><p>smaller 与 neater 是并列比较级；than mine 中 mine 代替 my garden，比较的是花园而非主人。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-008">进入本课</a></p><h2 id="lesson-9-·-一般过去时与事件顺序" tabindex="-1">Lesson 9 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-9-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 9 · 一般过去时与事件顺序 {#lesson-9-·-一般过去时与事件顺序}&quot;">​</a></h2><ul><li>at half past eight — 在八点半</li><li>wait in silence — 静静等候，silence 在这里不可数</li></ul><p><strong>句型示范：</strong> The crowd reached the square at half past eight.</p><p>reached 是及物动词，后直接接 the square；at half past eight 是具体钟点，不用 in。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-009">进入本课</a></p><h2 id="lesson-10-·-被动语态与信息重点" tabindex="-1">Lesson 10 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-10-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 10 · 被动语态与信息重点 {#lesson-10-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>be made of — 由……制成，强调材料可辨认</li><li>belong to — 属于，通常不用被动语态</li></ul><p><strong>句型示范：</strong> The old guitar was repaired by a local technician.</p><p>The old guitar 是承受动作的主语，was repaired 是一般过去时被动，by 短语指出执行者。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-010">进入本课</a></p><h2 id="lesson-11-·-现在完成时与过去时间" tabindex="-1">Lesson 11 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-11-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 11 · 现在完成时与过去时间 {#lesson-11-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>borrow something from somebody — 向某人借入某物</li><li>do somebody a favour — 帮某人一个忙</li></ul><p><strong>句型示范：</strong> Ravi has lent me his bicycle for the weekend.</p><p>Ravi 是借出者，has lent 是完成时，me 是接收者，for the weekend 说明借用时段。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-011">进入本课</a></p><h2 id="lesson-12-·-将来表达与安排" tabindex="-1">Lesson 12 · 将来表达与安排 <a class="header-anchor" href="#lesson-12-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 12 · 将来表达与安排 {#lesson-12-·-将来表达与安排}&quot;">​</a></h2><ul><li>set off — 出发，可用 for 引出目的地</li><li>wave goodbye — 挥手告别</li></ul><p><strong>句型示范：</strong> Our neighbour is sailing to the island on Friday.</p><p>is sailing 是现在进行时表将来安排，on Friday 明确日期，to the island 表示目的地。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-012">进入本课</a></p><h2 id="lesson-13-·-将来进行时与过程" tabindex="-1">Lesson 13 · 将来进行时与过程 <a class="header-anchor" href="#lesson-13-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 13 · 将来进行时与过程 {#lesson-13-·-将来进行时与过程}&quot;">​</a></h2><ul><li>give a concert — 举办一场音乐会</li><li>at that time — 在那个时候，需有清楚的时间参照</li></ul><p><strong>句型示范：</strong> At seven tomorrow, the band will be rehearsing in the hall.</p><p>At seven tomorrow 建立未来参照点，will be rehearsing 表示该时刻正在进行的活动，in the hall 是地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-013">进入本课</a></p><h2 id="lesson-14-·-过去进行时与叙事背景" tabindex="-1">Lesson 14 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-14-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 14 · 过去进行时与叙事背景 {#lesson-14-·-过去进行时与叙事背景}&quot;">​</a></h2><ul><li>ask for directions — 问路，directions 常用复数</li><li>speak slowly — 慢慢说，slowly 修饰 speak</li></ul><p><strong>句型示范：</strong> I was looking for the station when a cyclist offered help.</p><p>I was looking 是持续背景，when 引出 offered；offer help 中 help 是不可数名词。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-014">进入本课</a></p><h2 id="lesson-15-·-间接引语与视角转换" tabindex="-1">Lesson 15 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-15-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 15 · 间接引语与视角转换 {#lesson-15-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>tell somebody that — 告诉某人……</li><li>feel relieved — 感到放心，relieved 描述人的感受</li></ul><p><strong>句型示范：</strong> The manager told Hana that her work was excellent.</p><p>told 的宾语是 Hana，that 引出所说内容；her 指 Hana，was 在过去视角下转述评价。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-015">进入本课</a></p><h2 id="lesson-16-·-情态动词的意义与形式" tabindex="-1">Lesson 16 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-16-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 16 · 情态动词的意义与形式 {#lesson-16-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>move away from — 从……移开</li><li>be allowed to — 被允许做某事</li></ul><p><strong>句型示范：</strong> Could you move your car away from the entrance, please?</p><p>Could 位于主语 you 前形成问句，后接 move 原形；away from 引出应远离的位置，please 缓和语气。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-016">进入本课</a></p><h2 id="lesson-17-·-一般现在时与习惯" tabindex="-1">Lesson 17 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-17-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 17 · 一般现在时与习惯 {#lesson-17-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>look young — 看上去年轻，look 后接形容词</li><li>take part in — 参与活动，in 不可随意省略</li></ul><p><strong>句型示范：</strong> My aunt always looks cheerful before a performance.</p><p>My aunt 是主语，looks 是系动词，cheerful 是表语；always 表示频率，不修饰形容词程度。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-017">进入本课</a></p><h2 id="lesson-18-·-一般现在时与习惯" tabindex="-1">Lesson 18 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-18-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 18 · 一般现在时与习惯 {#lesson-18-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>look for — 寻找，侧重过程</li><li>find out — 查明信息，不等同于找见某个物品</li></ul><p><strong>句型示范：</strong> Our dog often hides my bag under the sofa.</p><p>often 放在实义动词 hides 前；my bag 是宾语，under the sofa 是地点，第三人称单数动词加 -s。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-018">进入本课</a></p><h2 id="lesson-19-·-情态动词的意义与形式" tabindex="-1">Lesson 19 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-19-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 19 · 情态动词的意义与形式 {#lesson-19-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>sell out — 售罄，活动或票可作主语</li><li>be in a queue — 在排队，queue 是可数名词</li></ul><p><strong>句型示范：</strong> Two seats may become available if someone cancels.</p><p>may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-019">进入本课</a></p><h2 id="lesson-20-·-动名词与动词搭配" tabindex="-1">Lesson 20 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-20-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 20 · 动名词与动词搭配 {#lesson-20-·-动名词与动词搭配}&quot;">​</a></h2><ul><li>be interested in — 对……感兴趣，in 后可接 -ing</li><li>spend time doing — 花时间做某事</li></ul><p><strong>句型示范：</strong> Ben enjoys fishing beside the old bridge.</p><p>enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-020">进入本课</a></p><h2 id="lesson-21-·-被动语态与信息重点" tabindex="-1">Lesson 21 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-21-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 21 · 被动语态与信息重点 {#lesson-21-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>put up with — 忍受，with 后接名词或动名词</li><li>decide to stay — 决定留下，decide 后接 to 不定式</li></ul><p><strong>句型示范：</strong> Our sleep is disturbed by early flights.</p><p>Our sleep 是承受影响的主语，is disturbed 是现在时被动，by early flights 表原因来源。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-021">进入本课</a></p><h2 id="lesson-22-·-动词、宾语与补足语" tabindex="-1">Lesson 22 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-22-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 22 · 动词、宾语与补足语 {#lesson-22-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>reply to a message — 回复一条消息</li><li>hear from somebody — 收到某人的来信或消息</li></ul><p><strong>句型示范：</strong> A walker replied to the message inside the bottle.</p><p>replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-022">进入本课</a></p><h2 id="lesson-23-·-被动语态与信息重点" tabindex="-1">Lesson 23 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-23-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 23 · 被动语态与信息重点 {#lesson-23-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>move into — 搬进某处，强调进入新住所</li><li>under construction — 正在施工，不用 a 修饰 construction</li></ul><p><strong>句型示范：</strong> A new footpath is being built behind our house.</p><p>A new footpath 是主语，is being built 是现在进行时被动；behind our house 是地点，不是动作执行者。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-023">进入本课</a></p>',120)])])}const f=s(l,[["render",i]]);export{u as __pageData,f as default};
